def dedup_lines(in_path, out_path, mode='exact'):
    def key_fn(s):
        if mode == 'normalized':
            return ' '.join(s.strip().lower().split())
        return s.rstrip('\n')
    seen = set()
    total = 0
    unique = 0
    with open(in_path, 'r', encoding='utf-8', errors='replace') as fin, open(out_path, 'w', encoding='utf-8') as fout:
        for line in fin:
            total += 1
            k = key_fn(line)
            if k not in seen:
                seen.add(k)
                fout.write(line if line.endswith('\n') else line + '\n')
                unique += 1
    return {'total': total, 'unique': unique, 'removed': total - unique}

import re
from collections import Counter
TOK = re.compile(r'[a-z0-9]+')
def keyword_freq(paths, stopwords=(), top_k=20, include_bigrams=False):
    stops = {s.lower() for s in stopwords}
    uni = Counter()
    bi = Counter()
    total = 0
    for p in paths:
        prev = None
        with open(p, 'r', encoding='utf-8', errors='replace') as f:
            for line in f:
                toks = [t for t in TOK.findall(line.lower()) if t not in stops]
                total += len(toks)
                uni.update(toks)
                if include_bigrams:
                    for a, b in zip([prev] + toks[:-1] if prev else toks[:-1], toks if prev is None else ([prev] + toks)[1:]):
                        pass
                    seq = ([prev] + toks) if prev else toks
                    for a, b in zip(seq, seq[1:]):
                        bi[a + ' ' + b] += 1
                    prev = toks[-1] if toks else prev
    top_uni = [[w, c] for w, c in sorted(uni.items(), key=lambda kv: (-kv[1], kv[0]))[:top_k]]
    top_bi = [[w, c] for w, c in sorted(bi.items(), key=lambda kv: (-kv[1], kv[0]))[:top_k]] if include_bigrams else []
    return {'unigrams': top_uni, 'bigrams': top_bi, 'total_tokens': total}

import re
EMAIL = re.compile(r'[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}')
PHONE = re.compile(r'(?:\+?\d{1,3}[-.\s]?)?(?:\(\d{2,4}\)[-.\s]?|\d{2,4}[-.\s]?){2,3}\d{3,4}')
IP = re.compile(r'\b(?:\d{1,3}\.){3}\d{1,3}\b')
PATS = {'email': EMAIL, 'phone': PHONE, 'ip': IP}
def extract_pii(paths, entity_types=('email','phone','ip')):
    matches = []
    masked = {}
    summary = {t: 0 for t in entity_types}
    for p in paths:
        with open(p, 'r', encoding='utf-8', errors='replace') as f:
            text = f.read()
        spans = []
        for t in entity_types:
            for m in PATS[t].finditer(text):
                v = m.group(0)
                if t == 'ip' and not all(0 <= int(x) <= 255 for x in v.split('.')):
                    continue
                matches.append({'type': t, 'value': v, 'start': m.start(), 'end': m.end(), 'file': p})
                spans.append((m.start(), m.end(), t))
                summary[t] += 1
        spans.sort()
        out = []
        last = 0
        for s, e, t in spans:
            if s < last:
                continue
            out.append(text[last:s])
            out.append(f'<{t.upper()}>')
            last = e
        out.append(text[last:])
        masked[p] = ''.join(out)
    matches.sort(key=lambda d: (d['file'], d['start']))
    return {'matches': matches, 'masked': masked, 'summary': summary}

from datetime import datetime
import itertools
FMT1 = '%Y-%m-%dT%H:%M:%S'
FMT2 = '%d/%b/%Y:%H:%M:%S %z'
def _parse_ts(s):
    s = s.strip()
    for f in (FMT1, '%Y-%m-%d %H:%M:%S'):
        try:
            return datetime.strptime(s[:19], f)
        except ValueError:
            pass
    if s.startswith('['):
        inner = s[1:].split(']')[0]
        try:
            return datetime.strptime(inner.strip(), FMT2).replace(tzinfo=None)
        except ValueError:
            pass
    raise ValueError('bad ts')
def build_timeline(paths):
    events = []
    bad = {}
    seq = itertools.count()
    for p in paths:
        c = 0
        with open(p, 'r', encoding='utf-8', errors='replace') as f:
            for line in f:
                line = line.rstrip('\n')
                if not line.strip():
                    c += 1
                    continue
                parts = line.split(' ', 1)
                try:
                    if line.startswith('['):
                        end = line.index(']')
                        ts = _parse_ts(line[:end+1])
                        msg = line[end+1:].strip()
                    else:
                        ts = _parse_ts(parts[0])
                        msg = parts[1] if len(parts) > 1 else ''
                except (ValueError, IndexError):
                    c += 1
                    continue
                events.append((ts, next(seq), msg, p))
        bad[p] = c
    events.sort(key=lambda e: (e[0], e[1]))
    tl = [{'timestamp_iso': e[0].isoformat(), 'message': e[2], 'source': e[3]} for e in events]
    return {'timeline': tl, 'bad_lines': bad, 'total': len(tl)}

import re
TOK = re.compile(r'[a-z0-9]+')
class MiniIndex:
    def __init__(self):
        self.idx = {}
    def build(self, doc_store):
        idx = {}
        for doc, path in doc_store.items():
            with open(path, 'r', encoding='utf-8', errors='replace') as f:
                terms = set(TOK.findall(f.read().lower()))
            for t in terms:
                idx.setdefault(t, []).append(doc)
        for t in idx:
            idx[t] = sorted(idx[t])
        self.idx = idx
        return idx
    def query(self, q):
        q = q.strip().lower()
        if ' or ' in q:
            out = set()
            for part in q.split(' or '):
                out |= set(self._one(part.strip()))
            return sorted(out)
        parts = q.split()
        res = None
        for part in parts:
            s = set(self._one(part))
            res = s if res is None else (res & s)
        return sorted(res or [])
    def _one(self, term):
        if term.endswith('*'):
            pre = term[:-1]
            out = set()
            for k, v in self.idx.items():
                if k.startswith(pre):
                    out.update(v)
            return sorted(out)
        return self.idx.get(term, [])

def build_index(doc_store):
    mi = MiniIndex()
    return mi.build(doc_store)

import re, hashlib
from itertools import combinations
TOK = re.compile(r'[A-Za-z0-9]+')
def chunk_dedup(paths, chunk_size=20, threshold=0.2):
    doc_chunks = {}
    h2files = {}
    for p in paths:
        with open(p, 'r', encoding='utf-8', errors='replace') as f:
            toks = TOK.findall(f.read().lower())
        hs = set()
        for i in range(0, max(1, len(toks) - chunk_size + 1)):
            h = hashlib.md5(' '.join(toks[i:i+chunk_size]).encode()).hexdigest()
            hs.add(h)
            h2files.setdefault(h, set()).add(p)
        doc_chunks[p] = hs
    dups = [{'chunk_hash': h, 'files': sorted(fs)} for h, fs in sorted(h2files.items()) if len(fs) > 1]
    pairs = []
    for a, b in combinations(sorted(doc_chunks), 2):
        sa, sb = doc_chunks[a], doc_chunks[b]
        union = len(sa | sb)
        ratio = (len(sa & sb) / union) if union else 0.0
        if ratio >= threshold:
            pairs.append([a, b, round(ratio, 4)])
    pairs.sort(key=lambda x: (-x[2], x[0], x[1]))
    return {'duplicates': dups, 'similar_pairs': pairs}

import re
def multi_search(path, patterns, case_insensitive=False, overlapping=False):
    flags = re.IGNORECASE if case_insensitive else 0
    counts = {p: 0 for p in patterns}
    lines = {p: [] for p in patterns}
    total = 0
    if not overlapping:
        alt = '|'.join(f'(?P<g{i}>' + re.escape(p) + ')' for i, p in enumerate(patterns))
        rx = re.compile(alt, flags)
        with open(path, 'r', encoding='utf-8', errors='replace') as f:
            for no, line in enumerate(f, 1):
                total += 1
                for m in rx.finditer(line):
                    for i, p in enumerate(patterns):
                        if m.group(f'g{i}') is not None:
                            counts[p] += 1
                            if not lines[p] or lines[p][-1] != no:
                                lines[p].append(no)
    else:
        rxs = [(p, re.compile(re.escape(p), flags)) for p in patterns]
        with open(path, 'r', encoding='utf-8', errors='replace') as f:
            for no, line in enumerate(f, 1):
                total += 1
                hay = line
                for p, rx in rxs:
                    pos = 0
                    found = False
                    while True:
                        m = rx.search(hay, pos)
                        if not m:
                            break
                        counts[p] += 1
                        found = True
                        pos = m.start() + 1
                    if found and (not lines[p] or lines[p][-1] != no):
                        lines[p].append(no)
    return {'counts': counts, 'lines': lines, 'total_lines': total}

from datetime import datetime, timezone
from collections import Counter
def detect_bursts(path, window_seconds=60, threshold=10, top_k=5):
    c = Counter()
    with open(path, 'r', encoding='utf-8', errors='replace') as f:
        for line in f:
            if 'ERROR' not in line:
                continue
            tok = line.strip().split(' ', 1)[0].strip('[]')
            try:
                dt = datetime.fromisoformat(tok.replace('Z', '+00:00'))
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=timezone.utc)
            except ValueError:
                continue
            epoch = int(dt.timestamp())
            w = (epoch // window_seconds) * window_seconds
            key = datetime.fromtimestamp(w, tz=timezone.utc).isoformat()
            c[key] += 1
    bursts = sorted([k for k, v in c.items() if v >= threshold])
    top = [[k, v] for k, v in sorted(c.items(), key=lambda kv: (-kv[1], kv[0]))[:top_k]]
    return {'windows': dict(c), 'bursts': bursts, 'top': top}

