from collections import defaultdict
def extract_sessions(path, gap_minutes=30):
    per = defaultdict(list)
    with open(path, 'r', encoding='utf-8', errors='replace') as f:
        for line in f:
            parts = line.strip().split(' ', 2)
            if len(parts) < 3:
                continue
            try:
                dt = datetime.fromisoformat(parts[0].replace('Z', '+00:00'))
            except ValueError:
                continue
            user, action = parts[1], parts[2]
            per[user].append((dt, action))
    out = []
    for user in sorted(per):
        evs = sorted(per[user], key=lambda e: e[0])
        if not evs:
            continue
        idx = 1
        start = prev = evs[0][0]
        cnt = 1
        for dt, _ in evs[1:]:
            if (dt - prev).total_seconds() > gap_minutes * 60:
                out.append({'session_id': f'{user}_{idx}', 'user': user, 'start': start.isoformat(), 'end': prev.isoformat(), 'count': cnt, 'duration_s': round((prev - start).total_seconds(), 2)})
                idx += 1
                start = dt
                cnt = 0
            prev = dt
            cnt += 1
        out.append({'session_id': f'{user}_{idx}', 'user': user, 'start': start.isoformat(), 'end': prev.isoformat(), 'count': cnt, 'duration_s': round((prev - start).total_seconds(), 2)})
    return {'sessions': out, 'total_sessions': len(out)}

import heapq, os
from datetime import datetime
def merge_logs(paths, out_path):
    def gen(p, base):
        seq = 0
        with open(p, 'r', encoding='utf-8', errors='replace') as f:
            for line in f:
                line = line.rstrip('\n')
                if not line.strip():
                    yield ('bad', None, None)
                    continue
                head, _, msg = line.partition(' ')
                try:
                    dt = datetime.fromisoformat(head.strip('[]').replace('Z', '+00:00'))
                except ValueError:
                    yield ('bad', None, None)
                    continue
                seq += 1
                yield ('ok', (dt, seq, base, msg.strip()))
    bad = {p: 0 for p in paths}
    iters = []
    for p in paths:
        base = os.path.basename(p)
        items = []
        for kind, val in gen(p, base):
            if kind == 'bad':
                bad[p] += 1
            else:
                items.append(val)
        iters.append(sorted(items, key=lambda x: (x[0], x[1])))
    merged = heapq.merge(*iters) if iters else []
    w = 0
    with open(out_path, 'w', encoding='utf-8') as out:
        for dt, _, base, msg in merged:
            out.write(f"{dt.isoformat()} | {base} | {msg}\n")
            w += 1
    return {'written': w, 'bad': bad}

import re
EMAIL = re.compile(r'[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}')
PHONE = re.compile(r'\+?\d[\d\-.\s]{7,}\d')
IP = re.compile(r'\b(?:\d{1,3}\.){3}\d{1,3}\b')
def redact(in_path, out_path, keywords=(), enabled=None):
    en = {'pii': True, 'keywords': True} if enabled is None else enabled
    kw_rx = re.compile('|'.join(re.escape(k) for k in keywords), re.IGNORECASE) if keywords and en.get('keywords') else None
    counts = {'email': 0, 'phone': 0, 'ip': 0, 'keyword': 0}
    total = 0
    with open(in_path, 'r', encoding='utf-8', errors='replace') as fin, open(out_path, 'w', encoding='utf-8') as fout:
        for line in fin:
            if en.get('pii'):
                line, n = EMAIL.subn('[EMAIL]', line); counts['email'] += n; total += n
                line, n = IP.subn('[IP]', line); counts['ip'] += n; total += n
                line, n = PHONE.subn('[PHONE]', line); counts['phone'] += n; total += n
            if kw_rx:
                line, n = kw_rx.subn('[KEYWORD]', line); counts['keyword'] += n; total += n
            fout.write(line)
    return {'redactions': counts, 'total': total}

import re
W = re.compile(r'[A-Za-z0-9]+')
def kwic(paths, keywords, window=5, max_hits=1000):
    kws = [k.lower() for k in keywords]
    kset = set(kws)
    hits = []
    per = {}
    for p in paths:
        with open(p, 'r', encoding='utf-8', errors='replace') as f:
            lines = f.readlines()
        for ln, line in enumerate(lines, 1):
            toks = W.findall(line)
            low = [t.lower() for t in toks]
            for i, t in enumerate(low):
                if t in kset:
                    l = toks[max(0, i-window):i]
                    r = toks[i+1:i+1+window]
                    hits.append({'keyword': t, 'file': p, 'line': ln, 'left': l, 'match': toks[i], 'right': r})
                    per[p] = per.get(p, 0) + 1
                    if len(hits) >= max_hits:
                        hits.sort(key=lambda h: (h['file'], h['line']))
                        return {'hits': hits, 'per_file': per, 'total': len(hits)}
    hits.sort(key=lambda h: (h['file'], h['line']))
    return {'hits': hits, 'per_file': per, 'total': len(hits)}

import csv
def extract_fields(in_path, out_path, delimiter='|', quotechar='"', columns=(0, 2), expected_fields=4):
    rows = bad = 0
    with open(in_path, 'r', encoding='utf-8', errors='replace', newline='') as fin, open(out_path, 'w', encoding='utf-8', newline='') as fout:
        r = csv.reader(fin, delimiter=delimiter, quotechar=quotechar)
        w = csv.writer(fout)
        for row in r:
            if not row or all(not c.strip() for c in row):
                bad += 1
                continue
            if len(row) != expected_fields:
                bad += 1
                continue
            try:
                w.writerow([row[i] for i in columns])
            except IndexError:
                bad += 1
                continue
            rows += 1
    return {'rows': rows, 'bad': bad}

from datetime import datetime, timezone
from collections import Counter
def gen_alerts(path, rules):
    lines = open(path, 'r', encoding='utf-8', errors='replace').readlines()
    alerts = []
    total_w = 0
    for r in rules:
        pat, ws, th, sev = r['pattern'], r['window_s'], r['threshold'], r.get('severity', 'HIGH')
        c = Counter()
        for line in lines:
            if pat not in line:
                continue
            head = line.strip().split(' ', 1)[0].strip('[]')
            try:
                dt = datetime.fromisoformat(head.replace('Z', '+00:00'))
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=timezone.utc)
            except ValueError:
                continue
            w = int(dt.timestamp()) // ws * ws
            key = datetime.fromtimestamp(w, tz=timezone.utc).isoformat()
            c[key] += 1
        total_w += len(c)
        for k in sorted(c):
            if c[k] >= th:
                alerts.append({'rule': pat, 'window_start_iso': k, 'count': c[k], 'severity': sev})
    alerts.sort(key=lambda a: (a['window_start_iso'], a['rule']))
    return {'alerts': alerts, 'windows_checked': total_w}

import re
START = re.compile(r'^(\[?\d{4}-\d{2}-\d{2}[T ]\S+\]?\s+\w+)')
LVL = re.compile(r'\b(DEBUG|INFO|WARN|ERROR|FATAL)\b')
def recover_log(in_path, out_path):
    rec = unrec = 0
    buf = ''
    valid = []
    def flush():
        nonlocal rec, unrec
        if not buf.strip():
            return
        if START.search(buf) and LVL.search(buf):
            valid.append(buf)
            if ' ' in buf and len(buf) > 0:
                pass
        else:
            unrec += 1
    with open(in_path, 'r', encoding='utf-8', errors='replace') as f:
        for line in f:
            s = line.rstrip('\n')
            if s[:1].isspace() and buf:
                buf += ' ' + s.strip()
                rec += 1
            else:
                if buf:
                    before = len(valid)
                    flush()
                buf = s
        if buf:
            flush()
    with open(out_path, 'w', encoding='utf-8') as o:
        for v in valid:
            o.write(v + '\n')
    return {'recovered': rec, 'unrecoverable': unrec, 'written': len(valid)}
